	/// <summary>
	/// Find user-defined protected methods that match interface method signatures
	/// </summary>
	private static EquatableArray<UserMethodInfo> GetUserDefinedMethods(
		INamedTypeSymbol classSymbol,
		List<InterfaceInfo> interfaces)
	{
		var userMethods = new List<UserMethodInfo>();

		// Get all methods declared directly on this class (not inherited)
		var classMethods = classSymbol.GetMembers()
			.OfType<IMethodSymbol>()
			.Where(m => m.MethodKind == MethodKind.Ordinary
				&& m.DeclaredAccessibility == Accessibility.Protected
				&& !m.IsStatic)
			.ToList();

		// Build a set of interface method signatures to match against
		var interfaceMethodSignatures = new HashSet<string>();
		foreach (var iface in interfaces)
		{
			foreach (var member in iface.Members)
			{
				if (!member.IsProperty)
				{
					var sig = GetMethodSignature(member.Name, member.ReturnType, member.Parameters, member.IsGenericMethod, member.TypeParameters);
					interfaceMethodSignatures.Add(sig);
				}
			}
		}

		// Find matching user methods
		foreach (var method in classMethods)
		{
			var returnType = method.ReturnType.ToDisplayString(FullyQualifiedWithNullability);
			var parameters = method.Parameters
				.Select(p => new ParameterInfo(p.Name, p.Type.ToDisplayString(FullyQualifiedWithNullability), p.RefKind))
				.ToArray();

			// Extract type parameters for generic methods
			var isGenericMethod = method.IsGenericMethod;
			var typeParameters = EquatableArray<TypeParameterInfo>.Empty;
			if (isGenericMethod)
			{
				typeParameters = new EquatableArray<TypeParameterInfo>(
					method.TypeParameters
						.Select(tp => new TypeParameterInfo(
							tp.Name,
							new EquatableArray<string>(SymbolHelpers.GetTypeParameterConstraints(tp).ToArray())))
						.ToArray());
			}

			var sig = GetMethodSignature(method.Name, returnType, new EquatableArray<ParameterInfo>(parameters), isGenericMethod, typeParameters);

			if (interfaceMethodSignatures.Contains(sig))
			{
				userMethods.Add(new UserMethodInfo(
					Name: method.Name,
					ReturnType: returnType,
					Parameters: new EquatableArray<ParameterInfo>(parameters),
					IsGenericMethod: isGenericMethod,
					TypeParameters: typeParameters));
			}
		}

		return new EquatableArray<UserMethodInfo>(userMethods.ToArray());
	}

	private static string GetMethodSignature(string name, string returnType, EquatableArray<ParameterInfo> parameters, bool isGenericMethod, EquatableArray<TypeParameterInfo> typeParameters)
	{
		var paramTypes = string.Join(",", parameters.Select(p => p.Type));
		// Include type parameter count to distinguish generic from non-generic overloads
		// Also include type parameter names since they affect return type and parameter types (e.g., T vs TResult)
		var typeParamSuffix = isGenericMethod
			? $"<{string.Join(",", typeParameters.Select(tp => tp.Name))}>"
			: "";
		return $"{returnType} {name}{typeParamSuffix}({paramTypes})";
	}

	/// <summary>
	/// Detects user-defined methods in all partial class declarations that have the 'override' modifier
	/// and end with the '_' suffix (our base class user method naming convention).
	/// Uses syntactic detection via DeclaringSyntaxReferences - the 'override' keyword is detected
	/// as a syntax token, which works even before the generated base class exists.
	/// </summary>
	/// <param name="classSymbol">The class symbol to scan for override methods</param>
	/// <returns>A set of method signature keys (format: "MethodName_(ParamType1,ParamType2,...)") that have user overrides</returns>
	private static HashSet<string> DetectUserOverrideMethods(INamedTypeSymbol classSymbol)
	{
		var overrideMethods = new HashSet<string>();

		// Iterate over ALL partial class declarations
		foreach (var syntaxRef in classSymbol.DeclaringSyntaxReferences)
		{
			var classSyntax = syntaxRef.GetSyntax() as ClassDeclarationSyntax;
			if (classSyntax == null)
				continue;

			foreach (var member in classSyntax.Members)
			{
				if (member is MethodDeclarationSyntax method)
				{
					// Check for override modifier (SYNTACTIC - works without base class!)
					if (method.Modifiers.Any(m => m.IsKind(SyntaxKind.OverrideKeyword)))
					{
						var methodName = method.Identifier.Text;
						// Check for our naming convention: ends with _
						if (methodName.EndsWith("_"))
						{
							// Build full signature key including parameter types
							var signatureKey = BuildOverrideSignatureKey(method);
							overrideMethods.Add(signatureKey);
						}
					}
				}
			}
		}

		return overrideMethods;
	}

	/// <summary>
	/// Builds a signature key from a MethodDeclarationSyntax for matching user override methods.
	/// Format: "MethodName_(ParamType1,ParamType2,...)" - NO return type since C# forbids return-type overloading.
	/// Includes ref/out/in modifiers as they affect the signature.
	/// </summary>
	private static string BuildOverrideSignatureKey(MethodDeclarationSyntax method)
	{
		var name = method.Identifier.Text;
		var paramParts = method.ParameterList.Parameters
			.Select(p =>
			{
				// Get modifier prefix (ref, out, in, ref readonly, params)
				var modifiers = p.Modifiers;
				var prefix = "";
				if (modifiers.Any(m => m.IsKind(SyntaxKind.RefKeyword)))
				{
					if (modifiers.Any(m => m.IsKind(SyntaxKind.ReadOnlyKeyword)))
						prefix = "ref readonly ";
					else
						prefix = "ref ";
				}
				else if (modifiers.Any(m => m.IsKind(SyntaxKind.OutKeyword)))
					prefix = "out ";
				else if (modifiers.Any(m => m.IsKind(SyntaxKind.InKeyword)))
					prefix = "in ";
				// Note: params not included - it doesn't affect method signature identity

				// Normalize the type name
				var typeName = NormalizeSyntaxType(p.Type?.ToString() ?? "object");
				return prefix + typeName;
			})
			.ToArray();
		return $"{name}({string.Join(",", paramParts)})";
	}

	/// <summary>
	/// Normalizes type names to match what users would write in their override methods.
	/// Handles common differences between semantic and syntax representations.
	/// </summary>
	private static string NormalizeSyntaxType(string type)
	{
		// Remove global:: prefix (user code won't have it)
		var result = type.Replace("global::", "");

		// Map fully qualified System types to keywords
		result = result switch
		{
			"System.String" => "string",
			"System.Int32" => "int",
			"System.Int64" => "long",
			"System.Boolean" => "bool",
			"System.Double" => "double",
			"System.Single" => "float",
			"System.Decimal" => "decimal",
			"System.Char" => "char",
			"System.Byte" => "byte",
			"System.SByte" => "sbyte",
			"System.Int16" => "short",
			"System.UInt16" => "ushort",
			"System.UInt32" => "uint",
			"System.UInt64" => "ulong",
			"System.Object" => "object",
			"System.Void" => "void",
			_ => result
		};

		return result;
	}
